# Generated by Selenium IDE / Automated Test Suite
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class TestAddService:
    def setup_method(self, method):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()
        self.wait = WebDriverWait(self.driver, 10)

    def teardown_method(self, method):
        self.driver.quit()

    def test_add_service(self):
        # 1. Login as Hospital Administrator
        self.driver.get("http://localhost:3000/login")
        self.wait.until(EC.visibility_of_element_located((By.NAME, "email"))).send_keys("admin@meditwin.local")
        self.driver.find_element(By.NAME, "password").send_keys("AdminPass@123")
        self.driver.find_element(By.CSS_SELECTOR, "button[type='submit']").click()
        
        # 2. Navigate to Hospital Services & Clinical Procedures Management
        self.wait.until(EC.url_contains("/dashboard/admin"))
        self.driver.get("http://localhost:3000/dashboard/admin/procedures")

        # 3. Click 'Add New Service / Procedure' button
        add_service_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(text(), 'Add Service') or contains(text(), 'Add Procedure') or contains(@id, 'btn-add-service')]"))
        )
        add_service_btn.click()

        # 4. Fill in hospital clinical service details
        service_title_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "title")))
        service_title_field.clear()
        service_title_field.send_keys("Electrocardiogram (ECG) Diagnostic Service")

        service_code_field = self.driver.find_element(By.NAME, "procedureCode")
        service_code_field.clear()
        service_code_field.send_keys("SOP-CARD-04")

        dept_select = self.driver.find_element(By.NAME, "departmentId")
        dept_select.send_keys("Cardiology")

        category_select = self.driver.find_element(By.NAME, "category")
        category_select.send_keys("Diagnostic & Imaging")

        fee_field = self.driver.find_element(By.NAME, "serviceFee")
        fee_field.clear()
        fee_field.send_keys("450.00")

        desc_field = self.driver.find_element(By.NAME, "description")
        desc_field.clear()
        desc_field.send_keys("12-lead resting electrocardiogram recording and automated cardiac rhythm analysis")

        status_select = self.driver.find_element(By.NAME, "status")
        status_select.send_keys("PUBLISHED")

        # 5. Click Publish / Save Service button
        publish_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(text(), 'Publish') or contains(text(), 'Save Service')]"))
        )
        publish_btn.click()

        # 6. Verify service creation toast and visibility in hospital services registry
        success_alert = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'Service added successfully') or contains(text(), 'Procedure created successfully')]"))
        )
        assert success_alert.is_displayed(), "Hospital service publish confirmation alert was not displayed."

        created_service = self.wait.until(
            EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'Electrocardiogram (ECG) Diagnostic Service')]"))
        )
        assert created_service.is_displayed(), "Newly added service is missing from clinical department registry."
